#!/usr/bin/env python3
"""Plot benchmark CSV generated by u55c_bench."""

from __future__ import annotations

import argparse
import csv
from collections import defaultdict
from pathlib import Path
from statistics import mean

import matplotlib.pyplot as plt


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Plot U55C benchmark CSV")
    parser.add_argument("--csv", required=True, help="Input CSV path")
    parser.add_argument("--out", required=True, help="Output plot PNG path")
    return parser.parse_args()


def main() -> int:
    args = parse_args()

    csv_path = Path(args.csv)
    out_path = Path(args.out)

    if not csv_path.exists():
        raise FileNotFoundError(f"CSV not found: {csv_path}")

    grouped = defaultdict(list)

    with csv_path.open("r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            elements = int(row["elements"])
            grouped[elements].append(
                {
                    "total_ms": float(row["total_ms"]),
                    "throughput_gbps": float(row["throughput_gbps"]),
                }
            )

    if not grouped:
        raise RuntimeError("no rows found in CSV")

    sizes = sorted(grouped.keys())
    avg_total_ms = [mean(sample["total_ms"] for sample in grouped[n]) for n in sizes]
    avg_tput = [mean(sample["throughput_gbps"] for sample in grouped[n]) for n in sizes]

    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(9, 8), sharex=True)

    ax1.plot(sizes, avg_total_ms, marker="o")
    ax1.set_title("Average End-to-End Latency")
    ax1.set_ylabel("ms")
    ax1.grid(True, alpha=0.3)

    ax2.plot(sizes, avg_tput, marker="o")
    ax2.set_title("Average Throughput")
    ax2.set_xlabel("Elements")
    ax2.set_ylabel("Gb/s")
    ax2.grid(True, alpha=0.3)

    fig.tight_layout()
    out_path.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(out_path, dpi=150)
    print(f"Saved plot: {out_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
